use dice::roll;

#[test]
fn cases() {
    let cases: Vec<(Vec<&str>, &str)> = vec![
        (vec!["3d6+2", "4 5 1"], "3d6: 4 5 1 = 10\ntotal 12"),
        (vec!["2d20-1d6", "18 4 5"], "2d20: 18 4 = 22\n1d6: 5 = 5\ntotal 17"),
        (vec!["d20*2", "5"], "d20: 5 = 5\ntotal 10"),
    ];
    for (i, (a, want)) in cases.iter().enumerate() {
        let got = roll(a[0], a[1]);
        assert_eq!(got, *want, "case {} {:?}", i, a);
    }
}

