MAXN = 10
MAXS = 20
HAS_MODS = True
HAS_ADV = True
CAP = 40
DG = "0123456789"


class Err(Exception):
    pass


class Parser:
    def __init__(self, s):
        self.s = s
        self.p = 0

    def peek(self):
        return self.s[self.p] if self.p < len(self.s) else ""

    def ws(self):
        while self.p < len(self.s) and self.s[self.p] in " \t":
            self.p += 1

    def integer(self, maxd):
        q = self.p
        while self.p < len(self.s) and self.s[self.p] in DG:
            self.p += 1
        if self.p == q or self.p - q > maxd:
            raise Err("syntax")
        return int(self.s[q:self.p])

    def expr(self):
        left = self.term()
        while True:
            self.ws()
            c = self.peek()
            if c in ("+", "-") and c != "":
                self.p += 1
                left = ("bin", c, left, self.term())
            else:
                return left

    def term(self):
        left = self.factor()
        while True:
            self.ws()
            if self.peek() == "*":
                self.p += 1
                left = ("bin", "*", left, self.factor())
            else:
                return left

    def factor(self):
        self.ws()
        c = self.peek()
        if c == "(":
            self.p += 1
            e = self.expr()
            self.ws()
            if self.peek() != ")":
                raise Err("syntax")
            self.p += 1
            return e
        if c == "-":
            self.p += 1
            return ("neg", self.factor())
        start = self.p
        if c != "" and c in DG:
            n = self.integer(4)
            if self.peek() != "d":
                return ("int", n)
        elif c == "d":
            n = 1
        else:
            raise Err("syntax")
        self.p += 1  # the 'd'
        if n < 1 or n > MAXN:
            raise Err("dice count")
        sides = self.integer(3)
        if sides < 2 or sides > MAXS:
            raise Err("sides")
        rr = 0
        expl = False
        keep = None
        cnt = 0
        if HAS_ADV and self.peek() == "r":
            self.p += 1
            rr = self.integer(3)
            if rr < 1 or rr >= sides:
                raise Err("reroll")
        if HAS_MODS and self.peek() == "!":
            self.p += 1
            expl = True
        if HAS_MODS and self.peek() in ("k", "d") and self.peek() != "":
            two = self.s[self.p:self.p + 2]
            if two in ("kh", "kl", "dh", "dl"):
                self.p += 2
                k = self.integer(3)
                if k < 1:
                    raise Err("keep")
                keep = (two, k)
        if HAS_ADV and self.peek() == "c":
            self.p += 1
            cnt = self.integer(3)
            if cnt < 1 or cnt > sides:
                raise Err("count")
        return ("dice", self.s[start:self.p], n, sides, rr, expl, keep, cnt)


def parse(src):
    p = Parser(src)
    tree = p.expr()
    p.ws()
    if p.p != len(src):
        raise Err("syntax")
    return tree


class State:
    def __init__(self, stream):
        self.toks = stream.split()
        self.i = 0
        self.lines = []

    def take(self, sides):
        if self.i >= len(self.toks):
            raise Err("stream exhausted")
        t = self.toks[self.i]
        self.i += 1
        if not (1 <= len(t) <= 9 and all(c in DG for c in t)) or not (1 <= int(t) <= sides):
            raise Err("bad roll " + t)
        return int(t)


def ev(node, st):
    k = node[0]
    if k == "int":
        return node[1]
    if k == "neg":
        return -ev(node[1], st)
    if k == "bin":
        a = ev(node[2], st)
        b = ev(node[3], st)
        return a + b if node[1] == "+" else a - b if node[1] == "-" else a * b
    _, text, n, sides, rr, expl, keep, cnt = node
    vals = [st.take(sides) for _ in range(n)]
    if rr:
        for i in range(len(vals)):
            if vals[i] <= rr:
                vals[i] = st.take(sides)
    if expl:
        i = 0
        while i < len(vals):
            if vals[i] == sides:
                if len(vals) >= CAP:
                    raise Err("too many dice")
                vals.append(st.take(sides))
            i += 1
    dropped = set()
    if keep:
        kind, kk = keep
        idx = list(range(len(vals)))
        if kind in ("kh", "dh"):
            idx.sort(key=lambda j: (-vals[j], j))
        else:
            idx.sort(key=lambda j: (vals[j], j))
        first = set(idx[:kk])
        if kind in ("kh", "kl"):
            dropped = set(range(len(vals))) - first
        else:
            dropped = first
    kept = [v for j, v in enumerate(vals) if j not in dropped]
    sub = sum(1 for v in kept if v >= cnt) if cnt else sum(kept)
    shown = " ".join(("(%d)" % v) if j in dropped else str(v) for j, v in enumerate(vals))
    st.lines.append("%s: %s = %d" % (text, shown, sub))
    return sub


def roll(expr, stream):
    try:
        tree = parse(expr)
        st = State(stream)
        total = ev(tree, st)
    except Err as e:
        return "error: " + str(e)
    return "\n".join(st.lines + ["total %d" % total])

