#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "dice.h"

static int failed = 0;

static void check(int i, char *got, const char *want) {
    if (!got || strcmp(got, want) != 0) {
        failed++;
        printf("case %d FAILED\n  got:  [%s]\n  want: [%s]\n", i, got ? got : "(null)", want);
    }
    free(got);
}

int main(void) {
    check(0, roll("3d6+2", "4 5 1"), "3d6: 4 5 1 = 10\ntotal 12");
    check(1, roll("2d8-1d6", "5 8 1"), "2d8: 5 8 = 13\n1d6: 1 = 1\ntotal 12");
    check(2, roll("d8*2", "5"), "d8: 5 = 5\ntotal 10");
    if (failed) {
        printf("%d case(s) failed\n", failed);
        return 1;
    }
    printf("all cases passed\n");
    return 0;
}
